// ---- Settings for the prototype -------------------------------------------
const CONFIG = {
  ollamaUrl: 'http://ollama:11434',
  embedModel: 'bge-m3',      // 1024-dim; must match vector(1024) in the schema
  llmModel: 'qwen2.5:7b',    // any Ollama model that handles JSON well
  topKEvidence: 5,           // submission chunks given to the LLM per rule
  topKKb: 3,                 // knowledge-base chunks given to the LLM per rule
  chunkSize: 1200,           // characters
  chunkOverlap: 200,
};
// ---------------------------------------------------------------------------

const req = $input.first();
const body = req.json.body || {};

const setCode = String(body.guidelineSet || '').trim();
if (!/^[A-Za-z0-9_-]{1,64}$/.test(setCode)) {
  throw new Error('"guidelineSet" is required (letters, digits, - or _ only)');
}
const output = String(body.output || 'json').toLowerCase() === 'text' ? 'text' : 'json';

let fields = body.fields || {};
if (typeof fields === 'string') {
  try { fields = JSON.parse(fields); } catch (e) { fields = { fields }; }
}

const meta = { setCode, output, fields, config: CONFIG };
const items = [];

// Free text and structured fields are analysed as a virtual document.
const inline = [];
if (body.text) inline.push(String(body.text));
const fieldLines = Object.entries(fields).map(
  ([k, v]) => `${k}: ${typeof v === 'object' ? JSON.stringify(v) : v}`
);
if (fieldLines.length) inline.push('Submission fields:\n' + fieldLines.join('\n'));
if (inline.length) {
  const txt = inline.join('\n\n');
  items.push({
    json: { ...meta, fileName: 'inline-submission.txt' },
    binary: {
      data: {
        data: Buffer.from(txt, 'utf8').toString('base64'),
        mimeType: 'text/plain',
        fileName: 'inline-submission.txt',
      },
    },
  });
}

// One item per uploaded file, whatever the multipart field names were.
for (const [key, bin] of Object.entries(req.binary || {})) {
  items.push({ json: { ...meta, fileName: bin.fileName || key }, binary: { data: bin } });
}

if (!items.length) throw new Error('Send at least one file or a "text" field');
return items;

function htmlToText(html) {
  return String(html)
    .replace(/<head[\s\S]*?<\/head>/gi, '')
    .replace(/<(script|style)[\s\S]*?<\/\1>/gi, '')
    .replace(/<br\s*\/?>|<\/(p|div|h[1-6]|li|tr)>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&')
    .replace(/[ \t]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function chunkText(text, size, overlap) {
  const out = [];
  let start = 0;
  while (start < text.length) {
    let end = Math.min(start + size, text.length);
    if (end < text.length) {
      const brk = Math.max(text.lastIndexOf('\n', end), text.lastIndexOf('. ', end));
      if (brk > start + size * 0.5) end = brk + 1;
    }
    const piece = text.slice(start, end).trim();
    if (piece) out.push(piece);
    if (end >= text.length) break;
    start = Math.max(end - overlap, start + 1);
  }
  return out;
}

// Tika returns XHTML; PDFs come back with one <div class="page"> per page.
function splitPages(html) {
  const parts = String(html).split(/<div class="page">/i);
  if (parts.length > 1) return parts.slice(1).map((p, i) => ({ page: i + 1, text: htmlToText(p) }));
  return [{ page: null, text: htmlToText(html) }];
}

const prepared = $('Prepare request').all();
const cfg = prepared[0].json.config;

const chunks = [];
$input.all().forEach((item, i) => {
  const fileName = prepared[i].json.fileName;
  for (const { page, text } of splitPages(item.json.data || '')) {
    for (const piece of chunkText(text, cfg.chunkSize, cfg.chunkOverlap)) {
      chunks.push({ id: 'S' + (chunks.length + 1), file: fileName, page, text: piece });
    }
  }
});

if (!chunks.length) {
  throw new Error('No text could be extracted from the submission (scanned file without OCR?)');
}
return [{ json: { chunks, embedModel: cfg.embedModel } }];

const req = $('Prepare request').first().json;
const rules = $input.all().map(i => i.json).filter(r => r && r.rule_code);

if (!rules.length) {
  throw new Error(`No active rules found for guideline set "${req.setCode}"`);
}
for (const r of rules) {
  if (!/^[A-Za-z0-9_.-]+$/.test(r.rule_code)) throw new Error('Invalid rule_code: ' + r.rule_code);
}
return [{ json: { rules, embedModel: req.config.embedModel } }];

function cosine(a, b) {
  let dot = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) { dot += a[i] * b[i]; na += a[i] * a[i]; nb += b[i] * b[i]; }
  return dot / (Math.sqrt(na) * Math.sqrt(nb) || 1);
}

const cfg = $('Prepare request').first().json.config;
const chunks = $('Split into chunks').first().json.chunks;
const chunkVecs = $('Embed submission').first().json.embeddings;
const rules = $('Check rules').first().json.rules;
const ruleVecs = $input.first().json.embeddings;

// One output item per rule = one LLM evaluation per rule (the "map" step).
return rules.map((r, i) => {
  const evidence = chunks
    .map((c, j) => ({ ...c, score: Math.round(cosine(ruleVecs[i], chunkVecs[j]) * 1000) / 1000 }))
    .sort((a, b) => b.score - a.score)
    .slice(0, cfg.topKEvidence);
  return {
    json: {
      ruleCode: r.rule_code,
      ruleText: r.rule_text,
      severity: r.severity,
      guidance: r.guidance,
      evidence,
      ruleVec: '[' + ruleVecs[i].join(',') + ']',
    },
  };
});

parameters.query:
=WITH q AS (SELECT '{{ $json.ruleVec }}'::vector AS v)
SELECT '{{ $json.ruleCode }}' AS rule_code,
       COALESCE(json_agg(t ORDER BY t.distance), '[]'::json) AS kb
FROM (
  SELECT 'K' || k.id AS id, k.source, k.page, k.content AS text,
         round((k.embedding <=> q.v)::numeric, 4) AS distance
  FROM kb_chunks k, q
  ORDER BY k.embedding <=> q.v
  LIMIT {{ $('Prepare request').first().json.config.topKKb }}
) t;

parameters.jsCode:
const cfg = $('Prepare request').first().json.config;
const selected = $('Select evidence').all().map(i => i.json);

const schema = {
  type: 'object',
  properties: {
    status: { type: 'string', enum: ['pass', 'fail', 'unclear', 'not_applicable'] },
    confidence: { type: 'number' },
    explanation: { type: 'string' },
    evidence: {
      type: 'array',
      items: {
        type: 'object',
        properties: { chunkId: { type: 'string' }, quote: { type: 'string' } },
        required: ['chunkId', 'quote'],
      },
    },
    kbReferences: { type: 'array', items: { type: 'string' } },
  },
  required: ['status', 'confidence', 'explanation', 'evidence', 'kbReferences'],
};

const system = `You are a meticulous regulatory reviewer. You evaluate ONE rule at a time against excerpts from an applicant's submission.

Decide the status:
- "pass": the SUBMISSION EXCERPTS clearly show the rule is met.
- "fail": the SUBMISSION EXCERPTS clearly show the rule is not met, or contain something that contradicts it.
- "unclear": the excerpts do not contain enough information to decide. The excerpts are only part of the submission, so missing information means "unclear", not "fail".
- "not_applicable": the excerpts show the rule does not apply to this submission.

Rules for your answer:
- Base the decision only on the SUBMISSION EXCERPTS. KNOWLEDGE BASE REFERENCES explain how to interpret the rule; they are never evidence that the submission complies.
- For "pass" or "fail", add evidence items. chunkId must be an S-id shown in the excerpts. quote must be copied word for word from that excerpt, at most 30 words.
- kbReferences: the K-ids you relied on, or an empty list.
- explanation: 1 to 3 plain sentences a human reviewer can check.
- confidence: a number between 0 and 1.
Respond with JSON only.`;

return $input.all().map(item => {
  const row = item.json;
  const r = selected.find(s => s.ruleCode === row.rule_code);
  const kb = Array.isArray(row.kb) ? row.kb : (typeof row.kb === 'string' ? JSON.parse(row.kb) : []);

  const where = (name, page) => `${name}${page ? ', page ' + page : ''}`;
  const kbText = kb.length
    ? kb.map(k => `[${k.id}] (${where(k.source, k.page)})\n${k.text}`).join('\n\n')
    : '(none)';
  const evText = r.evidence.map(e => `[${e.id}] (${where(e.file, e.page)})\n${e.text}`).join('\n\n');

  const user = [
    `RULE ${r.ruleCode} (severity: ${r.severity})`,
    r.ruleText,
    r.guidance ? `Reviewer guidance: ${r.guidance}` : '',
    '',
    'KNOWLEDGE BASE REFERENCES:',
    kbText,
    '',
    'SUBMISSION EXCERPTS:',
    evText,
  ].join('\n');

  return {
    json: {
      ruleCode: r.ruleCode,
      ruleText: r.ruleText,
      severity: r.severity,
      evidence: r.evidence,
      kb: kb.map(({ id, source, page }) => ({ id, source, page })),
      request: {
        model: cfg.llmModel,
        stream: false,
        format: schema,
        options: { temperature: 0, num_ctx: 8192 },
        messages: [
          { role: 'system', content: system },
          { role: 'user', content: user },
        ],
      },
    },
  };
});

const prompts = $('Build prompts').all().map(i => i.json);
const norm = s => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();

const findings = $input.all().map((item, i) => {
  const p = prompts[i];
  const base = { ruleCode: p.ruleCode, rule: p.ruleText, severity: p.severity };

  let r = null;
  try { r = JSON.parse((item.json.message && item.json.message.content) || ''); } catch (e) { r = null; }
  const statuses = ['pass', 'fail', 'unclear', 'not_applicable'];
  if (!r || !statuses.includes(r.status)) {
    return {
      ...base, status: 'unclear', confidence: 0,
      explanation: 'The model output could not be used; manual review needed.',
      evidence: [], kbReferences: [],
      checks: { parsed: false, notes: [item.json.error ? String(item.json.error.message || item.json.error) : 'Invalid JSON'] },
    };
  }

  // Every quote must really exist in the chunk the model cited.
  const byId = Object.fromEntries(p.evidence.map(e => [e.id, e]));
  const evidence = (r.evidence || []).map(ev => {
    const src = byId[ev.chunkId];
    return {
      chunkId: ev.chunkId,
      document: src ? src.file : null,
      page: src ? src.page : null,
      quote: ev.quote,
      verified: !!src && !!norm(ev.quote) && norm(src.text).includes(norm(ev.quote)),
    };
  });

  const notes = [];
  let status = r.status;
  if ((status === 'pass' || status === 'fail') && !evidence.some(e => e.verified)) {
    notes.push(`Model answered "${status}" but no quote could be verified in the submission; downgraded to "unclear".`);
    status = 'unclear';
  }

  const kbById = Object.fromEntries(p.kb.map(k => [k.id, k]));
  const kbReferences = (r.kbReferences || []).filter(id => kbById[id]).map(id => kbById[id]);

  const confidence = Math.max(0, Math.min(1, Number(r.confidence) || 0));
  return { ...base, status, confidence, explanation: r.explanation || '', evidence, kbReferences, checks: { parsed: true, notes } };
});

return [{ json: { findings } }];

const req = $('Prepare request').first().json;
const documents = $('Prepare request').all().map(i => i.json.fileName);
const { findings } = $input.first().json;

const count = s => findings.filter(f => f.status === s).length;
const counts = {
  pass: count('pass'), fail: count('fail'), unclear: count('unclear'),
  not_applicable: count('not_applicable'), total: findings.length,
};

let verdict = 'compliant';
if (findings.some(f => f.status === 'fail' && ['critical', 'major'].includes(f.severity))) verdict = 'non_compliant';
else if (counts.fail || counts.unclear) verdict = 'needs_review';

const result = {
  status: 'completed',
  guidelineSet: req.setCode,
  overall: { verdict, counts },
  summary: `${counts.fail} of ${counts.total} rules failed; ${counts.unclear} unclear; ${counts.pass} passed.`,
  findings,
  trace: {
    documents,
    embedModel: req.config.embedModel,
    llmModel: req.config.llmModel,
    analyzedAt: new Date().toISOString(),
  },
};

if (req.output !== 'text') {
  return [{ json: { contentType: 'application/json', responseBody: JSON.stringify(result, null, 2) } }];
}

const lines = [
  `Analysis report - guideline set: ${req.setCode}`,
  `Verdict: ${verdict.toUpperCase().replace('_', ' ')}`,
  result.summary,
  `Documents: ${documents.join(', ')}`,
  '',
];
const order = { fail: 0, unclear: 1, pass: 2, not_applicable: 3 };
for (const f of [...findings].sort((a, b) => order[a.status] - order[b.status])) {
  lines.push(`[${f.status.toUpperCase()}] ${f.ruleCode} (${f.severity}) ${f.rule}`);
  lines.push(`  Why: ${f.explanation}`);
  for (const e of f.evidence) {
    const loc = `${e.document || '?'}${e.page ? ', p.' + e.page : ''}`;
    lines.push(`  Evidence: "${e.quote}" (${loc}${e.verified ? '' : ', NOT VERIFIED'})`);
  }
  for (const n of f.checks.notes || []) lines.push(`  Note: ${n}`);
  lines.push('');
}
return [{ json: { contentType: 'text/plain; charset=utf-8', responseBody: lines.join('\n') } }];
